class IGOIconManager
{
public:
  class IconResource;
  class Icon
  {
    char data[100];

  public:
    IconResource *resource;
    int y;
    float vy;
    int sizeInterp;
    int state;
    bool show;
    char padding[3];
    float colorInterp;
    void Initialize(IconResource &res);
  };

  struct IconSpawn
  {
    float velocity;
    char padding[128];
  };

private:
  char padding0[2648];
  unsigned char numEffectIcons;
  unsigned char effectType;
  char padding1[106];
  int maxIcons;
  Icon *icons;
  Icon nextIcon;
  int numIcons;
  char padding2[8];
  int activeIcon;
  char padding3[52];
  int lastDropTime;
  char padding4[48];
  int prepareFailure;
  float effectTime;
  int startFail;
  char padding5[596];
  IconSpawn iconSpawns[16];
  char padding6[1951];
  unsigned char currentSpawn;

public:
  IconResource *FindResource(int trickIdx);
  void PopCompletedIcons(bool success);
  void PushBack(int trickIdx);
};

enum
{
  ICON_STATE_ACTIVE = 1,
  ICON_STATE_QUEUED = 0,
  ICON_STATE_FROZEN = 3,
  SS_ICON_FAILED_TRICKCHAIN = 10
};

class entity;
class SoundScriptManager
{
public:
  void playEvent(int type, entity *ent = 0, float value = 0.0f);
};

extern SoundScriptManager *g_sound_script_manager;
extern IGOIconManager::Icon *fallingIcon;

